sp_widget.client_script:
api.controller = function($scope, spUtil) {
  var c = this;
  c.user = {};

  c.submit = function() {
    if (!c.user.terms_acknowledged) {
      c.errorMessage = "You must accept the Terms & Conditions.";
      return;
    }

    // Clear messages
    c.errorMessage = '';
    c.successMessage = '';

    // Send data to server
    c.data.action = 'register';
    c.data.email = c.user.email;
    c.data.skills = c.user.skills;
    c.data.interests = c.user.interests;
    c.data.bio = c.user.bio;
    c.data.terms_acknowledged = c.user.terms_acknowledged;
    c.data.avatar = c.user.avatar;

    c.server.update().then(function(response) {
      var result = c.data.result;
      if (result.status === 'error') {
        c.errorMessage = result.message;
      } else {
        c.successMessage = "Registration successful!";
        c.user = {};
      }
    });
  };

  c.uploadAttachment = function(input) {
    var file = input.files[0];
    if (!file) return;

    spUtil.uploadAttachment(file, null, function(response) {
      if (response.sys_id) {
        c.user.avatar = response.sys_id;
      }
    });
  };
};

sp_widget.script:
(function() {
  if (input && input.action === 'register') {
    var email = input.email + '';
    var existing = new GlideRecord('x_1097288_hacktaho_user_profile');
    existing.addQuery('email', email);
    existing.query();
    if (existing.next()) {
      data.result = { status: 'error', message: 'Email already registered.' };
      return;
    }

    var newUser = new GlideRecord('x_1097288_hacktaho_user_profile');
    newUser.initialize();
    newUser.email = email;
    newUser.skills = input.skills;
    newUser.bio = input.bio;
    newUser.interests = input.interests;
    newUser.terms_acknowledged = input.terms_acknowledged;

    if (input.avatar)
      newUser.avatar = input.avatar;

    newUser.insert();

    data.result = { status: 'success' };
  }
})();
